async function FINISH(repeating = false) {
  if (g.EGRESS_C < 3) {
    crlf();
  }
  if (!repeating) {
    await V_SCORE();
    crlf();
  }
  await TELL_FINISH();
  await read(g.P_INBUF, g.P_LEXV);
  if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
    await restart();
    tell("Failed.\n");
    return await FINISH(true);
  } else if (eq(get(g.P_LEXV, 1), W.RESTOR)) {
    if (await restore()) {
      tell("Ok.\n");
      return true;
    } else {
      tell("Failed.\n");
      return await FINISH(true);
    }
  } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q)) {
    return await quit();
  } else {
    return await FINISH(true);
  }
}

