async function ROB(who, where = false) {
  let n_ = 0, x = 0;
  x = first(who);
  for (;;) {
    if (x == 0) {
      return true;
    }
    n_ = next(x);
    if ((where == BIGTOP) && hasFlag(x, WORNBIT)) {
      setFlag(x, REWEARBIT);
    }
    if ((where == PROTAGONIST) && hasFlag(x, REWEARBIT)) {
      setFlag(x, WORNBIT);
    } else {
      clearFlag(x, WORNBIT);
    }
    move(x, where);
    x = n_;
  }
}

async function MOVE_TAKEBIT(loc1, loc2) {
  let obj = 0;
  for (;;) {
    obj = await FIND_IN(loc1, TAKEBIT);
    if (obj) {
      move(obj, loc2);
    } else {
      return true;
    }
  }
}

