async function ARTICLE(obj, the = false) {
  if (!obj) {
    obj = NOT_HERE_OBJECT;
  }
  if (!(hasFlag(obj, NARTICLEBIT))) {
    if (the) {
      tell(" the");
    } else if (hasFlag(obj, NOA)) {
      tell(" ");
      await DPRINT(obj);
      return true;
    } else if (hasFlag(obj, VOWELBIT)) {
      tell(" an");
    } else {
      tell(" a");
    }
  }
  tell(" ");
  await DPRINT(obj);
  return true;
}

