async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0, x = false;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("[Those things aren't here!]\n");
    return true;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
  } else {
    tbl = g.P_PRSI;
    prso$ = false;
  }
  if (prso$) {
    if ((g.PRSA == V.FIND || g.PRSA == V.FOLLOW || g.PRSA == V.PHONE) || (g.PRSA == V.WHAT || g.PRSA == V.WHERE || g.PRSA == V.WHO) || (g.PRSA == V.WAIT_FOR || g.PRSA == V.WALK_TO || g.PRSA == V.PHONE_WITH) || (g.PRSA == V.BUY || g.PRSA == V.CALL) || ((g.PRSO == GIRL) && (g.PRSA == V.LISTEN) && (loc(GIRL) == LOCAL_GLOBALS))) {
      x = true;
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return true;
        }
      } else {
        return false;
      }
    }
  } else {
    if ((g.PRSA == V.ASK_ABOUT || g.PRSA == V.ASK_FOR || g.PRSA == V.TELL_ABOUT) || (g.PRSA == V.SEARCH_OBJECT_FOR)) {
      x = true;
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return true;
        }
      } else {
        return false;
      }
    }
  }
  if (x) {
    tell(S(g.SPECIFIC));
  } else if (g.WINNER == PROTAGONIST) {
    tell("[You can't ");
    if (g.P_XNAM == W.CONVER || g.P_XNAM == W.VOICE || g.P_XNAM == W.VOICES) {
      tell("hear");
    } else {
      tell("see");
    }
    if (!(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here.]\n");
  } else if ((THUMB == g.WINNER) || ((DICK == g.WINNER) && (hasFlag(DICK, RMUNGBIT) || g.DICK_UNRESPONSIVE))) {
    return false;
  } else if (g.WINNER == GUARD) {
    return false;
  } else {
    tell("Looking confused,");
    await ARTICLE(g.WINNER, true);
    tell(" says, \"I don't see");
    if (!(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!\"\n");
  }
  return await STOP();
}

async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0;
  m_f = await MOBY_FIND(tbl);
  if (1 == m_f) {
    if (prso$) {
      g.PRSO = g.P_MOBY_FOUND;
      g.P_IT_OBJECT = g.PRSO;
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    return false;
  } else if ((1 < m_f) && (obj = await apply(getProp(obj = get(tbl, 1), P.GENERIC)))) {
    if (obj == NOT_HERE_OBJECT) {
      return true;
    } else if (prso$) {
      g.PRSO = obj;
      g.P_IT_OBJECT = g.PRSO;
    } else {
      g.PRSI = obj;
    }
    return false;
  } else {
    return NOT_HERE_OBJECT;
  }
}

