async function LADDER_F() {
  if ((g.HERE == NEAR_WAGON) && !(hasFlag(LADDER, RMUNGBIT))) {
    return await CANT_SEE(LADDER);
  } else if (isVerb(V.TAKE)) {
    if (g.P_PRSA_WORD == W.TAKE || g.P_PRSA_WORD == W.GET || g.P_PRSA_WORD == W.REMOVE) {
      tell("It's not takeable.\n");
    } else {
      await PERFORM(V.CLIMB_FOO, LADDER);
    }
    return true;
  } else if (g.HERE == ON_TENT) {
    if (isVerb(V.EXAMINE, V.FIND, V.CLIMB_DOWN, V.CLIMB_FOO)) {
      if (await ENABLED$(I_POKE.id)) {
        tell("You desperately grope in the darkness for the rope ladder, but can't seem to find it.\n");
        return true;
      } else {
        tell("You can barely see the ladder. ");
        if (isVerb(V.CLIMB_DOWN, V.CLIMB_FOO)) {
          await DO_WALK(P.DOWN);
          return true;
        }
        crlf();
        return true;
      }
    } else {
      if (await ENABLED$(I_POKE.id)) {
        return await CANT_SEE(LADDER);
      } else {
        return false;
      }
    }
  } else if (g.END_GAME && (g.HERE == RING || g.HERE == PLATFORM_1) && !(eq(loc(PROTAGONIST), STAND)) && !(isVerb(V.UNTIE))) {
    if (await TOUCHING$(LADDER)) {
      return await DO_WALK(P.UP);
    } else if (isVerb(V.EXAMINE)) {
      return await TANGLED_ROPE(true);
    } else {
      return false;
    }
  } else if (isVerb(V.UNTIE, V.TAKE_WITH) && (g.PRSI == POLE)) {
    await PERFORM(V.UNTIE, LADDER);
    return true;
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_FOO) && (g.HERE == CLOWN_ALLEY)) {
    await PERFORM(V.BOARD, UPPER);
    return true;
  } else if (isVerb(V.CLIMB_FOO) && (g.HERE == ON_WAGON)) {
    await PERFORM(V.CLIMB_DOWN, LADDER);
    return true;
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_FOO)) {
    return await DO_WALK(P.UP);
  } else if (isVerb(V.CLIMB_DOWN)) {
    if (g.HERE == ON_WAGON) {
      if (!(await CLIMB$())) {
        if (await RUNNING$(I_OFFICE.id)) {
          await MUNRAB_ENTERS_OFFICE(true);
        }
        await GOTO(NEAR_WAGON);
        return true;
      }
      return true;
    } else {
      return await DO_WALK(P.DOWN);
    }
  } else {
    return false;
  }
}

async function CLIMB$() {
  let x = 0, to_ground$ = true, ground = false;
  if (g.END_GAME && (g.HERE == RING) && !(loc(PROTAGONIST) == STAND)) {
    tell("The rope ");
    await DPRINT(LADDER);
    tell(", which is tangled around its platform, dangles down a couple of feet out of your reach.\n");
    return true;
  } else if (await CANT_CLIMB$()) {
    x = first(PROTAGONIST);
    loop1: for (;;) {
      if (!(hasFlag(x, WORNBIT)) && !(x == BALLOON || x == MOUSE)) {
        break loop1;
      } else {
        x = next(x);
      }
    }
    if (ground = getProp(g.HERE, P.GROUND_LOC)) {
      move(x, ground);
    } else {
      to_ground$ = false;
      move(x, g.HERE);
    }
    tell("Trying to grip the ");
    await DPRINT(LADDER);
    tell(", you fumble away");
    await ARTICLE(x, true);
    if (to_ground$) {
      tell(" and it falls to the ground below");
    }
    tell(S(g.PERIOD));
    return true;
  } else if ((g.APE_LOC == 1) && (g.HERE == RING)) {
    g.APE_LOC = 2;
    clearFlag(PLATFORM_1, TOUCHBIT);
    tell("As you hoist ");
    await DPRINT(ME);
    tell(" onto the ");
    await DPRINT(LADDER);
    tell(", the platform buckles with the addition of your weight. ");
    await DPRINT(APE);
    tell(" is spooked, and ");
    if (!(loc(NET) == MUNRAB)) {
      tell("loses his bundle which falls tragically in front of your horrified face to the ground below.");
      return await FINISH();
    } else {
      tell("clambers up into the supporting apparatus as you board the platform.\n\n");
      if (eq(await META_LOC(RADIO), PLATFORM_1) && hasFlag(RADIO, ONBIT) && (g.STATION == 1170)) {
        tell("In his distress, ");
        await DPRINT(APE);
        tell(" must not have noticed the radio playing.\n\n");
      }
      await GOTO(PLATFORM_1);
      return true;
    }
  } else {
    return false;
  }
}

