async function PICK_CARD() {
  let num = 0, tmp = 0;
  if ((g.CARD_COUNT = g.CARD_COUNT + 1) > 52) {
    tell("\"I'm shuffling the decks now.\"\n");
    await SHUFFLE_DECK();
  }
  loop1: for (;;) {
    num = random(52) - 1;
    if (g.FORCED_BET) {
      num = 3 + random(47);
    }
    if ((tmp = get(g.CARD_TABLE, num)) == 0) {
      continue loop1;
    } else {
      put(g.CARD_TABLE, num, tmp - 1);
      return num;
    }
  }
}

async function CARD_VALUE(num) {
  return get(g.CARD_VALUES, div(num, 4));
}

async function DEAL_HAND(tbl) {
  put(tbl, 1, await PICK_CARD());
  put(tbl, 0, 1);
  put(tbl, 2, await PICK_CARD());
  return put(tbl, 0, 2);
}

async function TELL_HAND(tbl) {
  let cnt = get(tbl, 0), _1st = true;
  for (;;) {
    if (cnt == 0) {
      return true;
    } else {
      if (_1st) {
        _1st = false;
      } else {
        tell(" and the ");
      }
      await TELL_CARD(get(tbl, cnt));
      cnt = cnt - 1;
    }
  }
}

async function TELL_CARD(num) {
  tell(S(get(g.CARD_SPOT, div(num, 4))));
  tell(" of ");
  tell(S(get(g.CARD_SUIT, mod(num, 4))));
  return true;
}

async function PLAY_HAND(bet) {
  let tmp = 0, cnt = 0, dealer_hole = 0, val = false, dd = false;
  put(g.DEALER_HAND, 0, 0);
  put(g.YOUR_HAND, 0, 0);
  await DEAL_HAND(g.DEALER_HAND);
  await DEAL_HAND(g.YOUR_HAND);
  tell("The dealer gives you the ");
  await TELL_HAND(g.YOUR_HAND);
  tell(S(g.PERIOD));
  tell("He deals himself the ");
  await TELL_CARD(get(g.DEALER_HAND, 1));
  tell(" and one card down");
  if (loc(THUMB) == g.HERE) {
    tell(", which he peeks at");
  }
  tell(".\n\n");
  g.YOUR_COUNT = (await CARD_VALUE(get(g.YOUR_HAND, 1))) + (await CARD_VALUE(get(g.YOUR_HAND, 2)));
  g.DEALER_COUNT = (await CARD_VALUE(get(g.DEALER_HAND, 1))) + (await CARD_VALUE(get(g.DEALER_HAND, 2)));
  if (g.DEALER_COUNT == 21) {
    tell("The dealer turns over his hole card, which is the ");
    await TELL_CARD(get(g.DEALER_HAND, 2));
    tell(". \"Blackjack!\" he announces");
    if (g.YOUR_COUNT == 21) {
      tell(". You tie him for a push.\n");
      return 0;
    } else {
      tell(", as he collects your bet.\n");
      return bet * (-1);
    }
  } else if (g.YOUR_COUNT == 21) {
    tell("You show the dealer your blackjack, and he pays you ");
    bet = div(bet * 3, 2);
    await PRINT_AMOUNT(bet);
    tell(S(g.PERIOD));
    return bet;
  } else {
    g.FORCED_BET = false;
    dealer_hole = await CARD_VALUE(get(g.DEALER_HAND, 2));
    if (loc(THUMB) == g.HERE) {
      g.THUMB_TAPPED = true;
      tell("Inexplicably, you feel ");
      if (dealer_hole == 1 || dealer_hole == 11) {
        tell("one tap");
      } else {
        tell(N(dealer_hole), " taps");
      }
      tell(" on your foot.\n\n");
    }
  }
  loop1: for (;;) {
    tell("Do you want another card? (Y is affirmative): ");
    if (await YES$()) {
      cnt = get(g.YOUR_HAND, 0) + 1;
      put(g.YOUR_HAND, 0, cnt);
      put(g.YOUR_HAND, cnt, tmp = await PICK_CARD());
      tell("\nYou're dealt the ");
      await TELL_CARD(tmp);
      g.YOUR_COUNT = g.YOUR_COUNT + (await CARD_VALUE(tmp));
      if ((g.YOUR_COUNT > 21) && !(await ACE_CHECK())) {
        tell(" which puts you over 21, and the ");
        await DPRINT(DEALER);
        tell(" rakes in your bet.\n");
        val = 0 - bet;
        break loop1;
      } else {
        tell(S(g.PERIOD));
        continue loop1;
      }
    } else {
      if (g.YOUR_COUNT > 21) {
        await ACE_CHECK();
      }
      break loop1;
    }
  }
  tell("\nThe dealer turns up his hole card, the ");
  await TELL_CARD(get(g.DEALER_HAND, 2));
  if (val) {
    tell(", and smiles.\n");
    return val;
  } else {
    tell(".\n");
  }
  for (;;) {
    if ((g.DEALER_COUNT > 21) && !(await ACE_CHECK(false))) {
      tell("This gives him ", N(g.DEALER_COUNT), ", putting him over. He pays you ");
      await PRINT_AMOUNT(bet);
      tell(S(g.PERIOD));
      return bet;
    } else if (g.DEALER_COUNT > 16) {
      tell("He stops here, with ", N(g.DEALER_COUNT), ".");
      if (g.YOUR_COUNT > g.DEALER_COUNT) {
        tell(" You beat him and reap the payoff, ");
        await PRINT_AMOUNT(bet);
        tell(S(g.PERIOD));
        return bet;
      } else if (g.YOUR_COUNT == g.DEALER_COUNT) {
        tell(" Your hand ties his for a push.\n");
        return 0;
      } else {
        tell(" He beats you and rakes in your money.\n");
        return 0 - bet;
      }
    } else {
      cnt = get(g.DEALER_HAND, 0) + 1;
      put(g.DEALER_HAND, 0, cnt);
      put(g.DEALER_HAND, cnt, tmp = await PICK_CARD());
      g.DEALER_COUNT = g.DEALER_COUNT + (await CARD_VALUE(tmp));
      if (dd) {
        tell("He draws again");
      } else {
        tell("The dealer draws");
      }
      tell(" and picks up the ");
      await TELL_CARD(tmp);
      tell(S(g.PERIOD));
      dd = true;
    }
  }
}

async function ACE_CHECK(player$ = true) {
  let cnt = 0, tmp = 0, hnd = 0;
  if (player$) {
    hnd = g.YOUR_HAND;
  } else {
    hnd = g.DEALER_HAND;
  }
  cnt = get(hnd, 0);
  for (;;) {
    if (cnt == 0) {
      return false;
    } else if (eq(await CARD_VALUE(tmp = get(hnd, cnt)), 11)) {
      put(hnd, cnt, tmp + 52);
      if (player$) {
        g.YOUR_COUNT = g.YOUR_COUNT - 10;
        tmp = g.YOUR_COUNT;
      } else {
        g.DEALER_COUNT = g.DEALER_COUNT - 10;
        tmp = g.DEALER_COUNT;
      }
      if (tmp < 22) {
        return true;
      }
    }
    cnt = cnt - 1;
  }
}

async function SHUFFLE_DECK() {
  let cnt = 52;
  loop1: for (;;) {
    if (cnt == 0) {
      break loop1;
    } else {
      cnt = cnt - 1;
      put(g.CARD_TABLE, cnt, 4);
    }
  }
  g.CARD_COUNT = 0;
  await ALREADY_GONE(g.DEALER_HAND);
  return await ALREADY_GONE(g.YOUR_HAND);
}

async function ALREADY_GONE(hnd) {
  let cnt = 0, tmp = 0;
  cnt = get(hnd, 0);
  for (;;) {
    if (cnt == 0) {
      return true;
    } else {
      tmp = get(hnd, cnt);
      if ((tmp > 52) || (tmp == 52)) {
        tmp = tmp - 52;
      }
      put(g.CARD_TABLE, tmp, get(g.CARD_TABLE, tmp) - 1);
    }
    g.CARD_COUNT = g.CARD_COUNT + 1;
    cnt = cnt - 1;
  }
}

