async function BLUE_ROOM_F(rarg) {
  if (rarg == M_ENTER) {
    g.BLUE_ROOM_ENTER_NUMBER = g.BLUE_ROOM_ENTER_NUMBER + 1;
    if (hasFlag(DEALER, RMUNGBIT)) {
      move(TICKET, DEALER);
      enable(await QUEUE(I_CHASE.id, -1));
    }
    enable(await QUEUE(I_BLUE_DOOR.id, 1));
    tell("As you enter, a blue haze of smoke stings your eyeballs.\n\n");
    return true;
  } else if (rarg == M_LOOK) {
    tell("In the far ");
    await DPRINT(CORNER);
    tell(" of this tented enclosure a thick, undulating cloud of smoke hovers over a ");
    await DPRINT(POKER);
    tell(". Straight across from you a tight-jawed dealer stands over a ");
    await DPRINT(TABLE);
    tell(" covered with a green floor-length tablecloth.\n");
    return true;
  } else if (rarg == M_BEG) {
    if (!(g.BLUE_ROOM_ENTER_NUMBER == 1) && !(hasFlag(DEALER, RMUNGBIT))) {
      g.BOUNCE_C = g.BOUNCE_C + 1;
      if ((g.BOUNCE_C == 1) && g.HELPED_THUMB) {
        setFlag(THUMB, NDESCBIT);
        move(THUMB, g.HERE);
      } else if ((g.BOUNCE_C > 20) && (g.BLUE_ROOM_ENTER_NUMBER == 2)) {
        enable(await QUEUE(KICKED_OUT_FIRST_TIME.id, 1));
      }
    } else if ((g.CHASE_C > 2) && ((await TALKING_TO$(DEALER)) || (await TALKING_TO$(CON)) || (isVerb(V.GIVE, V.SHOW) && (g.PRSI == DEALER || g.PRSI == CON)))) {
      tell("You get no response from him.\n");
      g.P_CONT = false;
      return true;
    }
    if (isVerb(V.BET)) {
      if (hasFlag(DEALER, RMUNGBIT)) {
        if (loc(DEALER) == g.HERE) {
          tell("He refuses to deal with you.\n");
          g.P_IT_OBJECT = DEALER;
        } else {
          tell("All bets are off.\n");
        }
        return true;
      } else if (g.PRSO == DOLLAR) {
        return false;
      } else if ((g.PRSO == GLOBAL_MONEY) || ((g.P_AMOUNT == 0) || !g.P_AMOUNT)) {
        await SPECIFY_MONEY(true);
        return M_FATAL;
      } else if ((g.PRSO == INTNUM) && !g.P_DOLLAR_FLAG) {
        await SPECIFY_MONEY(true);
        return M_FATAL;
      } else if (!(g.PRSO == INTNUM || g.PRSO == DOLLAR)) {
        tell("You can only bet money.\n");
      } else if (g.POCKET_CHANGE < g.P_AMOUNT) {
        tell("You can't bet more than you have.\n");
        await STOP();
      } else if ((g.POCKET_CHANGE > 30326) && (g.BLUE_ROOM_ENTER_NUMBER == 2)) {
        tell("The ");
        await DPRINT(DEALER);
        tell(" examines your winnings.");
        await EIGHTY_SIX();
      } else if (25 > g.P_AMOUNT) {
        tell("\"The minimum bet is 25 cents.\"\n");
        await STOP();
      } else if (200 < g.P_AMOUNT) {
        tell("\"No bets over 2 dollars. House rules.\"\n");
      } else {
        if (!g.BET_ONCE) {
          tell("The ");
          await DPRINT(DEALER);
          tell(" shuffles the four decks and breathes a sigh.\n");
        }
        g.BET_ONCE = true;
        if ((g.BLUE_ROOM_ENTER_NUMBER == 2) || (g.HELPED_THUMB && ((g.POCKET_CHANGE > 23000) || (g.POCKET_CHANGE < 401)))) {
          g.BLUE_ROOM_ENTER_NUMBER = 2;
          g.FORCED_BET = true;
          setFlag(THUMB, NDESCBIT);
          move(THUMB, g.HERE);
        }
        g.POCKET_CHANGE = g.POCKET_CHANGE + (await PLAY_HAND(g.P_AMOUNT));
      }
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

