async function BIGTOP_F() {
  if (isVerb(V.CRAWL_UNDER, V.BOARD)) {
    if ((g.HERE == MIDWEST) || ((g.HERE == UNDER_STANDS) && hasFlag(BIGTOP, RMUNGBIT))) {
      tell("You creep under the side wall of the ");
      await DPRINT(BIGTOP);
      if (g.HERE == UNDER_STANDS) {
        tell(", right where you crawled in before");
      }
      tell(S(g.PERIOD));
      crlf();
      setFlag(BIGTOP, RMUNGBIT);
      if (g.HERE == UNDER_STANDS) {
        return await GOTO(MIDWEST);
      } else {
        return await GOTO(UNDER_STANDS);
      }
    } else if (g.HERE == FAT_EAST || g.HERE == FAT_WEST) {
      g.PRSO = FAT;
      return await TELL_HIT_HEAD();
    } else {
      return await TENT_BOUND();
    }
  } else if (isVerb(V.WALK_TO, V.THROUGH)) {
    if ((g.HERE == CON_AREA || g.HERE == WINGS || g.HERE == MIDWEST) || (g.HERE == BESIDE_BIGTOP)) {
      return await DO_WALK(P.NORTH);
    } else if ((g.HERE == WINGS || g.HERE == RING || g.HERE == DEN) || (g.HERE == STANDS_ROOM || g.HERE == UNDER_STANDS)) {
      tell(S(g.LOOK_AROUND), "\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.LEAVE, V.EXIT, V.DISEMBARK)) {
    if (g.HERE == WINGS || g.HERE == RING) {
      return await DO_WALK(P.SOUTH);
    } else if (g.HERE == DEN) {
      return await DO_WALK(P.EAST);
    } else if (g.HERE == STANDS_ROOM || g.HERE == UNDER_STANDS) {
      return await V_WALK_AROUND();
    } else {
      tell(S(g.LOOK_AROUND), "\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE) && !(g.HERE == FAT_EAST || g.HERE == FAT_WEST)) {
    tell("Soiled by endless miles of travel and heavily patched in places, the wide blue-and-white stripes nevertheless rise up to");
    if (hasFlag(g.HERE, INDOORSBIT)) {
      tell(" meet at the top of the towering center pole.\n");
      return true;
    } else {
      tell(" the black sky above.\n");
      return true;
    }
  } else if ((g.HERE == FAT_EAST || g.HERE == FAT_WEST) && isVerb(V.LOOK_UNDER, V.RAISE)) {
    return await NOT_PEEP();
  } else if (isVerb(V.TAKE, V.REMOVE) && (g.HERE == FAT_EAST || g.HERE == FAT_WEST)) {
    return await KIND_OF_PERFORMER();
  } else {
    return false;
  }
}

