async function PLATFORM_F() {
  if (await IS_ADJ$(W.OPPOSITE)) {
    if (isVerb(V.WALK_TO, V.THROUGH)) {
      if (g.HEADING_EAST$ || (g.HERE == PLATFORM_1)) {
        return await DO_WALK(P.EAST);
      } else if (g.HERE == PLATFORM_2) {
        return await DO_WALK(P.WEST);
      } else {
        return false;
      }
    } else if (await TOUCHING$(PLATFORM)) {
      return await CANT_REACH(PLATFORM);
    } else {
      return false;
    }
  } else if (isVerb(V.LOOK_ON) && (g.HERE == PLATFORM_1 || g.HERE == PLATFORM_2)) {
    await V_LOOK();
    return true;
  } else if (isVerb(V.PUT_ON)) {
    if (g.HERE == PLATFORM_1 || g.HERE == PLATFORM_2) {
      await PERFORM(V.DROP, g.PRSO);
      return true;
    } else {
      return await CANT_REACH(PLATFORM);
    }
  } else if (isVerb(V.THROUGH, V.WALK_TO, V.BOARD)) {
    if (g.HERE == PLATFORM_1 || g.HERE == PLATFORM_2) {
      tell(S(g.LOOK_AROUND), "\n");
      return true;
    } else if (g.HERE == TIGHTROPE_ROOM) {
      if (g.HEADING_EAST$) {
        return await DO_WALK(P.EAST);
      } else {
        return await DO_WALK(P.WEST);
      }
    } else {
      return await CANT_SEE(PLATFORM);
    }
  } else if (isVerb(V.LEAP, V.LEAP_OFF)) {
    if ((g.HERE == TIGHTROPE_ROOM) && isVerb(V.LEAP_OFF)) {
      tell(S(g.LOOK_AROUND), "\n");
      return true;
    } else {
      tell(S(g.UNBALANCED));
      await FLYING();
      tell("And you fall ...");
      return await FALL_DOWN();
    }
  } else {
    return false;
  }
}

