async function ACROSS_ROPE() {
  if (((g.P_WALK_DIR == P.WEST) && g.HEADING_EAST$) || ((g.P_WALK_DIR == P.EAST) && !g.HEADING_EAST$)) {
    if (g.END_GAME) {
      if (g.ON_ROPE == 1) {
        g.ON_ROPE = 5;
      } else if (g.ON_ROPE == 2) {
        g.ON_ROPE = 4;
      } else if (g.ON_ROPE == 4) {
        g.ON_ROPE = 2;
      } else if (g.ON_ROPE == 5) {
        g.ON_ROPE = 1;
      }
      if (g.HEADING_EAST$) {
        g.HEADING_EAST$ = false;
      } else {
        g.HEADING_EAST$ = true;
      }
      tell("A daring turnaround on the tightrope! You regain your balance.\n");
      return false;
    } else {
      tell("A bold attempt to excite the arena seats! ");
      await FLYING();
      tell("You sink ...");
      await FALL_DOWN();
      return false;
    }
  } else if (await RUNNING$(I_TREMBLE.id)) {
    if (g.TREMBLE_C == 0) {
      tell("A quiver shoots through your leading foot,");
    } else if (g.TREMBLE_C == 2 || g.TREMBLE_C == 3) {
      tell("Your trailing foot begins to quake,");
    } else {
      tell("You're too unstable.\n");
      return false;
    }
    tell(" stopping you dead on the wire.\n");
    return false;
  } else if (!(g.ON_ROPE == 5)) {
    g.ON_ROPE = g.ON_ROPE + 1;
    tell("You take a couple of tentative steps across the wire");
    if (g.ON_ROPE == 3) {
      tell(", reaching the halfway point");
    }
    if ((g.APE_LOC == 3) && g.HEADING_EAST$) {
      if (g.ON_ROPE == 2) {
        tell(". ");
        await DPRINT(APE);
        tell(" lets out an aggressive scream that echoes throughout the ");
        await DPRINT(BIGTOP);
        tell(".");
      } else if (g.ON_ROPE == 3) {
        tell(". The gorilla raps his knuckles against his mighty chest. You can feel the vibration on your toes.");
      } else if (g.ON_ROPE == 4) {
        if ((await HELD$(RADIO)) && (g.STATION == 1170) && hasFlag(RADIO, ONBIT) && g.CALLED_STATION) {
          tell(". As the heavenly music drifts to within earshot of ");
          await DPRINT(APE);
          tell(", the beast is becalmed, and he loosens his grip on the girl.");
        } else {
          tell(". ");
          await DPRINT(APE);
          tell(" appears determined to bring down the ");
          await DPRINT(BIGTOP);
          tell(" if you take one more step.");
        }
      } else if (g.ON_ROPE == 5) {
        if ((await HELD$(RADIO)) && (g.STATION == 1170) && hasFlag(RADIO, ONBIT) && g.CALLED_STATION) {
          g.APE_LOC = 4;
          await ROB(PROTAGONIST, LOCAL_GLOBALS);
          await MOVE_TAKEBIT(RING, WINGS);
          await ROB(RING, LEFT_HANGING);
          move(GIRL, LEFT_HANGING);
          move(THUMB, LEFT_HANGING);
          move(GANG, LEFT_HANGING);
          move(MUNRAB, LEFT_HANGING);
          g.END_GAME_C = 0;
          move(TIGHTROPE_OBJECT, LEFT_HANGING);
          tell(". You are now almost close enough to reach out and touch ");
          await DPRINT(APE);
          tell(", and the effect of the music is to utterly relax the great ape. He lets loose the girl like a rag doll ... falling ... falling ... falling ... deep into the safety of the net!\n\nThe cheers of joy and relief from the group encircling the net interrupt ");
          await DPRINT(APE);
          tell("'s listening pleasure. With a stomp, he bounces you off your perch and on your way down, you catch the wire with ");
          await DPRINT(HANDS);
          tell(", thus saving two lives in the same move. You dangle here as the crowd below continues their self-congratulation and rejoicing.\n\n");
          setFlag(MUNRAB, NDESCBIT);
          setFlag(THUMB, NDESCBIT);
          g.POCKET_CHANGE = 0;
          g.SCORE = g.SCORE + 10;
          await GOTO(LEFT_HANGING);
          return false;
        } else {
          (await JIGS_UP(1, ". With a stomp of its big foot, the ape bounces you off the wire and sends you into a swan dive. You miss the net, which is properly positioned under Chelsea."));
        }
      } else {
        return false;
      }
      crlf();
      return false;
    } else {
      tell(" ...\n");
      return TIGHTROPE_ROOM;
    }
  } else {
    return await PLATFORM_RETURN();
  }
}

