    await DPRINT(TRAP);
    tell(" is");
    if (hasFlag(TRAP, RMUNGBIT)) {
      tell(" not");
    }
    tell(" set");
    if (loc(CHEESE) == TRAP) {
      tell("; there is a bit of cheese in the trap");
    } else if (loc(MOUSE) == TRAP) {
      tell(". A ");
      await DPRINT(DEAD_MOUSE);
      tell(" rests under the bar");
    }
    tell(S(g.PERIOD));
