async function COAT_F() {
  let $1;
  if (isVerb(V.LOOK_INSIDE, V.SEARCH, V.SEARCH_OBJECT_FOR, V.OPEN) && (g.HERE == MIDWEST) && g.DICK_DRUNK) {
    tell("You're unable to search the coat thoroughly, since the ");
    await DPRINT(DICK);
    tell(" is wearing it.\n");
    return true;
  } else if ((g.HERE == PROP_ROOM) && ((await TOUCHING$(COAT)) || isVerb(V.LOOK_INSIDE))) {
    return await CANT_REACH(DICK);
  } else if ((g.HERE == MIDWEST) && !g.DICK_DRUNK && isVerb(V.LOOK_INSIDE, V.OPEN, V.CLOSE, V.SEARCH, V.PICK)) {
    await PERFORM(V.TAKE, FLASK);
    return true;
  } else if (isVerb(V.CLOSE)) {
    return await V_DIG();
  } else if (isVerb(V.PUT) && (g.PRSI == COAT)) {
    return await V_DIG();
  } else if (isVerb(V.TAKE, V.REMOVE, V.OPEN)) {
    if (g.DICK_DRUNK) {
      tell("It's harder than trying to husk an ear of corn; you finally give up.\n");
      return true;
    } else {
      $1 = await PICK_ONE(g.YUKS);
      tell(S($1));
      tell("\n");
      return true;
    }
  } else {
    return false;
  }
}

