async function CANT_WALK$() {
  if (isVerb(V.WALK)) {
    if ((loc(THUMB) == PROTAGONIST) && (g.HERE == WEST_CAMP || g.HERE == EAST_CAMP) && (g.P_WALK_DIR == P.NORTH)) {
      return await DONT_WALK(THUMB);
    } else if ((loc(GIRL) == PROTAGONIST) && (((g.HERE == EAST_CAMP) && (g.P_WALK_DIR == P.WEST || g.P_WALK_DIR == P.EAST)) || ((g.HERE == BACK_YARD) && !(g.P_WALK_DIR == P.EAST)) || ((g.HERE == NEAR_WAGON) && !(g.P_WALK_DIR == P.SOUTH)))) {
      return await DONT_WALK(GIRL);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DONT_WALK(person) {
  if (person == THUMB) {
    await DPRINT(THUMB);
    tell(" gets restless in your arms");
  } else {
    await DPRINT(GIRL);
    tell(" looks afraid");
  }
  tell(" when you start that way so you stop.\n");
  return true;
}

async function CANVAS_F() {
  if (isVerb(V.EXAMINE)) {
    if ((await RUNNING$(I_MEET.id)) && (await IS_ADJ$(W.SHADOW))) {
      tell("Very ominous.\n");
      return true;
    } else if (!(hasFlag(CANVAS, RMUNGBIT)) && (g.HERE == PROP_ROOM)) {
      return false;
    } else {
      tell("The ");
      await DPRINT(CANVAS);
      tell(" is deeply shadowed by its many pleats.\n");
      return true;
    }
  } else if ((g.HERE == WEST_CAMP) && isVerb(V.OPEN, V.RUB, V.RAISE, V.LOOK_UNDER, V.LOOK_INSIDE, V.MOVE)) {
    tell("One pleat opens up to reveal more darkly shadowed pleats.\n");
    return true;
  } else if (isVerb(V.WALK_TO, V.BOARD, V.THROUGH, V.CRAWL_UNDER) && (g.HERE == WEST_CAMP || g.HERE == PROP_ROOM)) {
    if ((g.HERE == WEST_CAMP) || hasFlag(CANVAS, RMUNGBIT)) {
      if (!(hasFlag(CANVAS, RMUNGBIT))) {
        g.SCORE = g.SCORE + 10;
      }
      await TELL_PASS_CANVAS();
      setFlag(CANVAS, RMUNGBIT);
      if (g.HERE == WEST_CAMP) {
        return await GOTO(PROP_ROOM);
      } else {
        return await GOTO(WEST_CAMP);
      }
    } else {
      tell("This side of the tent is too dark and shadowy to make out the confines of the ");
      await DPRINT(CANVAS);
      tell(".\n");
      return true;
    }
  } else {
    return false;
  }
}

