async function CRAWL_SPACE_F() {
  if (isVerb(V.LOOK_INSIDE)) {
    tell("It is completely dark inside the opening.\n");
    return true;
  } else if (isVerb(V.REACH_IN)) {
    if (loc(GIRL) == g.HERE) {
      await PERFORM(V.TAKE, GIRL);
      return true;
    } else {
      return await TELL_WITHIN_REACH();
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("The square hole is about a foot wide.\n");
    return true;
  } else if (isVerb(V.PUT_ON) && (g.PRSO == MOOSE)) {
    await PERFORM(V.PUT_ON, MOOSE, WALLS);
    return true;
  } else if (isVerb(V.PUT)) {
    if (g.PRSO == GIRL) {
      return false;
    } else if (getProp(g.PRSO, P.SIZE) < 75) {
      setFlag(g.PRSO, INVISIBLE);
      move(g.PRSO, CRAWL_SPACE);
      if (g.PRSO == THUMB) {
        enable(await QUEUE(I_TAMER.id, 3));
        tell("A wide-eyed ");
        await DPRINT(THUMB);
        tell(" goes easily through the opening and");
      } else {
        tell("As you release");
        await ARTICLE(g.PRSO, true);
        tell(" it");
      }
      tell(" drops to the floor on the other side of the wall. ");
      if ((loc(GIRL) == LOCAL_GLOBALS) && !g.GIRL_CRIED) {
        await TELL_WIMPER();
        return true;
      } else {
        crlf();
        return true;
      }
    } else {
      tell("It doesn't fit.");
    }
    return crlf();
  } else if (isVerb(V.BOARD, V.ENTER, V.THROUGH)) {
    tell("Despite your writhing and squirming at the opening, it would seem only a contortionist or a Houdini would fit through it.\n");
    return true;
  } else {
    return false;
  }
}

