async function I_BOOST() {
  g.BOOST_COUNTER = g.BOOST_COUNTER + 1;
  if (g.BOOST_COUNTER == 7) {
    return await BOOST_EXIT();
  } else {
    if (g.HERE == CON_AREA) {
      crlf();
      if (g.BOOST_COUNTER == 1) {
        tell("The last of the crowd just now trickles eastward through the ");
        await DPRINT(TURNSTILE);
        tell(".\n\nA midget decked out in a Russian general's uniform is standing before");
      } else if (g.BOOST_COUNTER == 2) {
        tell("The little general gets up on his tiptoes in front of");
      } else if (g.BOOST_COUNTER == 3) {
        tell("Attempting to do a pull-up, Comrade Thumb manages to sprawl himself onto");
      } else if (g.BOOST_COUNTER == 4) {
        tell("Straining his neck to reach the spout, the midget gropes for the button, loses his grip and plops to the ");
        await DPRINT(GROUND);
        tell(" before");
      } else if (g.BOOST_COUNTER == 5) {
        tell("The midget looks up at you sadly, then at");
      } else if (g.BOOST_COUNTER == 6) {
        tell("Comrade Thumb flaps his little arms once in frustration,");
        await BOOST_EXIT();
        return false;
      }
      tell(" the ");
      await DPRINT(FOUNTAIN);
      tell(".\n");
      return true;
    } else {
      return false;
    }
  }
}

async function BOOST_EXIT() {
  move(THUMB, LOCAL_GLOBALS);
  disable(await INT(I_BOOST.id));
  move(CROWD, STANDS_ROOM);
  if ((g.HERE == CON_AREA) && (g.BOOST_COUNTER < 7)) {
    tell(" and waddles off into the darkness.\n");
    g.FOLLOW_FLAG = 1;
    enable(await QUEUE(I_FOLLOW.id, 2));
  }
  return true;
}

async function JOEY_DESC(x = 0) {
  if (await RUNNING$(I_CLOWN_ALLEY.id)) {
    tell("Chuckles the clown is leaning in front of a mirror, removing his makeup.");
    return true;
  } else if (g.HERE == BACK_YARD) {
    tell("A tall and lanky clown in baggy pants trudges out of the ");
    if (g.P_WALK_DIR == P.EAST) {
      await DPRINT(DARKNESS);
    } else {
      tell("tent");
    }
    tell(" and toward the ");
    await DPRINT(TURNSTILE);
    tell(". ");
    await DPRINT(THUMB);
    tell(" follows behind.");
    return true;
  } else if (g.HERE == EAST_CAMP) {
    tell("Chuckles is standing, out of costume, in front of the aluminum trailer.");
    if (g.WIPE_C == 0) {
      tell(" As you approach, ");
      if (await JOKE_TIME$(g.JOEY_JOKE)) {
        g.JOEY_JOKE = true;
        tell("he glances at you and says, \"Pick up an application at the ");
        await DPRINT(WAGON);
        tell(", not here.\"");
        return true;
      } else {
        tell("he begins polishing away at it.");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function JOEY_F() {
  if (g.WINNER == JOEY) {
    if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.ASK_ABOUT, JOEY, g.PRSI);
      g.WINNER = JOEY;
      return true;
    } else if (isVerb(V.HELLO)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.HELLO, JOEY);
      g.WINNER = JOEY;
      return true;
    } else if (isVerb(V.YOU_ARE_OBJECT) && (g.PRSO == EDDIE)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.TELL, EDDIE);
      g.WINNER = JOEY;
      return true;
    } else {
      tell(S(g.BEAT_IT));
      return await STOP();
    }
  } else if (isVerb(V.ASK_ABOUT, V.TELL_ABOUT) && (g.PRSI == EDDIE) && hasFlag(EDDIE, RMUNGBIT)) {
    await PERFORM(V.HELLO, EDDIE);
    return true;
  } else if ((await TALKING_TO$(JOEY)) && (await RUNNING$(I_CLOWN_ALLEY.id))) {
    await PERFORM(V.RUB, JOEY);
    return true;
  } else if ((await TALKING_TO$(JOEY)) && !(isVerb(V.TELL))) {
    tell(S(g.BEAT_IT));
    return await STOP();
  } else if (isVerb(V.FOLLOW)) {
    if (g.FOLLOW_FLAG == 2) {
      return await DO_WALK(P.SOUTH);
    } else if (g.FOLLOW_FLAG == 3) {
      return await DO_WALK(P.WEST);
    } else if (g.FOLLOW_FLAG == 4) {
      return await DO_WALK(P.EAST);
    } else {
      return false;
    }
  } else if (isVerb(V.GIVE, V.SHOW) && (g.PRSI == JOEY || g.PRSI == EDDIE)) {
    g.P_IT_OBJECT = JOEY;
    if ((g.PRSO == RIBBON) && !(hasFlag(RIBBON, RMUNGBIT))) {
      g.SCARE_NUMBER = g.SCARE_NUMBER + 1;
      setFlag(RIBBON, RMUNGBIT);
      if (await JOEY_SCARED$()) {
        return M_FATAL;
      } else if (hasFlag(TRADE_CARD, RMUNGBIT)) {
        await HATE_TO_SEE();
        return await ELBOW_GREASE();
      } else {
        tell("\"Never saw it before in my life.\"\n");
        return true;
      }
    } else if ((g.PRSO == TRADE_CARD) && !(hasFlag(TRADE_CARD, RMUNGBIT))) {
      g.SCARE_NUMBER = g.SCARE_NUMBER + 1;
      setFlag(TRADE_CARD, RMUNGBIT);
      if (await JOEY_SCARED$()) {
        return M_FATAL;
      } else if (hasFlag(RIBBON, RMUNGBIT)) {
        tell("\"That ribbon in her hair looks like yours.\" He pauses. ");
        await HATE_TO_SEE();
        await ELBOW_GREASE();
        return true;
      } else {
        tell("\"Good product. I'd highly recommend it.\"\n");
        return true;
      }
    } else if ((g.PRSO == SCRAP) && !(hasFlag(SCRAP, RMUNGBIT))) {
      setFlag(SCRAP, RMUNGBIT);
      g.SCARE_NUMBER = g.SCARE_NUMBER + 1;
      await DPRINT(JOEY);
      tell(" looks skeptically at the ");
      await DPRINT(SCRAP);
      tell(" while listening to you tell where you found it. ");
      if (await JOEY_SCARED$(true)) {
        return M_FATAL;
      } else if (hasFlag(NOTE, RMUNGBIT)) {
        await CHERRY_PIE();
        await ELBOW_GREASE();
      } else {
        tell("\n\n\"Yea, I make paper dolls for the local kids. It's part of my act. So what?\"\n");
      }
      return true;
    } else if ((g.PRSO == NOTE) && !(hasFlag(NOTE, RMUNGBIT))) {
      setFlag(NOTE, RMUNGBIT);
      g.SCARE_NUMBER = g.SCARE_NUMBER + 1;
      tell("He reads the ");
      await DPRINT(NOTE);
      tell(", silently mouthing the words. ");
      if (await JOEY_SCARED$(true)) {
        return M_FATAL;
      } else if (hasFlag(SCRAP, RMUNGBIT)) {
        await CHERRY_PIE();
        await ELBOW_GREASE();
      } else {
        tell("He deadpans, \"Fascinating. Don't let the ");
        await DPRINT(DICK);
        tell(" find you with that.\"\n");
      }
      return true;
    } else if ((g.PRSO == SHEET) && !(hasFlag(SHEET, RMUNGBIT))) {
      setFlag(SHEET, RMUNGBIT);
      g.SCARE_NUMBER = g.SCARE_NUMBER + 1;
      tell("Chuckles's eyes dart between the various numbers in the multiple columns on the ");
      await DPRINT(SHEET);
      tell(". ");
      if (await JOEY_SCARED$(true)) {
        return M_FATAL;
      } else if (g.JOEY_NAME_KNOWN) {
        tell("\"So what? It's tough all over. I don't hold any grudge against ");
        await DPRINT(MUNRAB);
        tell(". Hell, I'm just a clown, a happy clown.\" ");
        return await ELBOW_GREASE();
      } else {
        tell("\"I don't know anyone by that name.\"\n");
        return true;
      }
    } else if (g.PRSO == SHEET || g.PRSO == NOTE || g.PRSO == SCRAP || g.PRSO == RIBBON || g.PRSO == TRADE_CARD) {
      tell("He ignores it this time.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function HATE_TO_SEE() {
  tell("\"I'd hate to be caught red-handed holding that ");
  await DPRINT(RIBBON);
  tell(" if I were you.\" ");
  return true;
}

async function I_JOEY() {
  g.WIPE_C = g.WIPE_C + 1;
  if (g.WIPE_C == 8) {
    move(JOEY, LOCAL_GLOBALS);
    if (g.HERE == EAST_CAMP) {
      (await TELL_SCREWS("enters"));
      g.FOLLOW_FLAG = 4;
      enable(await QUEUE(I_FOLLOW.id, 2));
      tell(" the ");
      await DPRINT(TAMER_TRAILER);
      tell(".\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.HERE == EAST_CAMP) && (g.WIPE_C == 2 || g.WIPE_C == 4 || g.WIPE_C == 6) && !(isVerb(V.SHOW, V.GIVE) && (g.PRSI == JOEY))) {
    tell("\n");
    await DPRINT(JOEY);
    tell(" dribbles a little Dr. Nostrum's onto his rag and continues wiping away at the ");
    await DPRINT(TAMER_TRAILER);
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

async function ELBOW_GREASE() {
  await DPRINT(JOEY);
  if (g.SCARE_NUMBER == 2) {
    tell(", unable to mask his concern,");
  } else if (g.SCARE_NUMBER == 3) {
    tell(", looking unclownly and perturbed,");
  } else if (g.SCARE_NUMBER == 4) {
    tell(" does a slow burn as he continues cleaning the ");
    await DPRINT(TAMER_TRAILER);
    tell(".\n");
    return true;
  }
  tell(" applies extra elbow grease to his cleaning.\n");
  return true;
}

async function JOEY_SCARED$(crlf$ = false) {
  if (g.JOEY_NAME_KNOWN && hasFlag(NOTE, RMUNGBIT) && hasFlag(SHEET, RMUNGBIT) && hasFlag(SCRAP, RMUNGBIT) && hasFlag(TRADE_CARD, RMUNGBIT) && hasFlag(RIBBON, RMUNGBIT)) {
    g.WON_JOEY = true;
    disable(await INT(I_JOEY.id));
    move(JOEY, LOCAL_GLOBALS);
    g.SCORE = g.SCORE + 10;
    if (crlf$) {
      crlf();
      crlf();
    }
    (await TELL_SCREWS("hustles off to the west"));
    g.FOLLOW_FLAG = 3;
    enable(await QUEUE(I_FOLLOW.id, 2));
    tell(S(g.PERIOD));
    return true;
  } else {
    return false;
  }
}

async function TELL_SCREWS(string) {
  if (g.WON_JOEY) {
    tell("Looking like a clown with a hotfoot, ");
  }
  await DPRINT(JOEY);
  tell(" suddenly screws the cap onto the flask of Dr. Nostrum's and ", S(string));
  return true;
}

async function CHERRY_PIE() {
  tell("\n\n\"So you think you've fingered me for this note. Pretty thin stuff, if you ask me. Besides, I've got no gripes against the bossman. Why, here I am doing cherry pie in the middle of the night.\" ");
  return true;
}

async function CLOWN_ALLEY_F(rarg) {
  if (rarg == M_LOOK) {
    tell("The gut of the trailer exposes the underside of circus life -- grungy costumes strewn about, crooked and cracked mirrors, the musty odor of fresh makeup mingled with clown sweat infusing the air.\n\nAgainst the wall is a row of cramped-looking bunks, and running from the floor to one ");
    await DPRINT(UPPER);
    tell(" is a small ladder. ");
    if (first(UPPER) || first(LOWER)) {
      tell(S(g.YOU_SEE));
      if (first(LOWER)) {
        await PRINT_BUNKS(LOWER, UPPER);
      } else {
        await PRINT_BUNKS(UPPER, LOWER);
      }
    }
    return crlf();
  } else if (rarg == M_ENTER) {
    await STEP_INTO_TRAILER();
    if (!g.CLOWN_ALLEY_SCENE) {
      g.CLOWN_ALLEY_SCENE = true;
      g.CLOWN_COUNTER = 0;
      return enable(await QUEUE(I_CLOWN_ALLEY.id, -1));
    } else {
      return false;
    }
  } else if ((rarg == M_BEG) && (await ENABLED$(I_CLOWN_ALLEY.id))) {
    if ((isVerb(V.REMOVE, V.TAKE_OFF) && (g.PRSO == MASK)) || !(hasFlag(MASK, WORNBIT))) {
      clearFlag(MASK, WORNBIT);
      tell("Y");
      return await UNMASK();
    } else if (await DISTURB$(JOEY)) {
      if (g.FOLLOW_FLAG == 99) {
        crlf();
      }
      tell("Chuckles whirls around, strips you of your disguise and y");
      return await UNMASK();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function PRINT_BUNKS(b1, b2) {
  await PRINT_CONTENTS(b1);
  tell(" sitting on the ");
  await DPRINT(b1);
  if (first(b2)) {
    tell(", and");
    await PRINT_CONTENTS(b2);
    tell(" on the ");
    await DPRINT(b2);
  }
  tell(".");
  return true;
}

async function EXIT_CLOWN_ALLEY() {
  if (!(hasFlag(WARPED_DOOR, OPENBIT))) {
    tell("The ");
    await DPRINT(WARPED_DOOR);
    tell(" is closed.\n");
    return false;
  } else if ((await RUNNING$(I_CLOWN_ALLEY.id)) && (await HELD$(TRAY))) {
    move(TRAY, LOCAL_GLOBALS);
    await DPRINT(JOEY);
    tell(" notices a little squirreliness on your part, confronts you, grabs the ");
    await DPRINT(TRAY);
    tell(", and throws you out.\n\n");
    return WEST_CAMP;
  } else {
    return WEST_CAMP;
  }
}

async function CLOWN_TRAILER_F() {
  if (isVerb(V.EXAMINE)) {
    if (g.HERE == WEST_CAMP) {
      tell("It's a vintage model that's seen plenty of bad road. The door, which is ");
      if (hasFlag(WARPED_DOOR, OPENBIT)) {
        tell("open");
      } else {
        tell("closed");
      }
      tell(", appears warped.\n");
      return true;
    } else {
      return await V_LOOK();
    }
  } else if (isVerb(V.SMELL) && (g.HERE == CLOWN_ALLEY)) {
    await PERFORM(V.SMELL);
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE, V.UNLOCK, V.LOCK)) {
    await PERFORM(g.PRSA, WARPED_DOOR, g.PRSI);
    return true;
  } else if (isVerb(V.WALK_TO, V.THROUGH, V.ENTER)) {
    if (g.HERE == WEST_CAMP) {
      return await DO_WALK(P.IN);
    } else if (g.HERE == CLOWN_ALLEY) {
      tell(S(g.LOOK_AROUND), "\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_CLOWN_ALLEY() {
  if (hasFlag(WARPED_DOOR, RMUNGBIT)) {
    clearFlag(WARPED_DOOR, RMUNGBIT);
    return false;
  }
  g.CLOWN_COUNTER = 1 + g.CLOWN_COUNTER;
  if (!(g.HERE == CLOWN_ALLEY) && hasFlag(WARPED_DOOR, OPENBIT)) {
    disable(await INT(I_CLOWN_ALLEY.id));
    clearFlag(WARPED_DOOR, OPENBIT);
    setFlag(WARPED_DOOR, LOCKEDBIT);
    if (g.HERE == WEST_CAMP) {
      tell("\nThe ");
      await DPRINT(WARPED_DOOR);
      tell(" is slammed shut.\n");
      return true;
    } else {
      return false;
    }
  } else {
    if (g.CLOWN_COUNTER == 2) {
      g.P_IT_OBJECT = WARPED_DOOR;
      tell("\nChuckles speaks, \"Sorry about the door, Malcom, but Johnny Tin Plate's out there nosing around.");
      if (hasFlag(WARPED_DOOR, OPENBIT)) {
        tell(" Close it, will you?");
      }
      tell("\"");
    } else if ((g.CLOWN_COUNTER == 3) && !g.HELPED_THUMB) {
      tell("\n");
      await DPRINT(THUMB);
      tell(" mutters something in Russian to Chuckles.\n\n");
      await PERFORM(V.RUB, JOEY);
      return true;
    } else if (g.CLOWN_COUNTER == 4) {
      tell("\n\"Let's just hope he doesn't find the grift.");
      if (hasFlag(WARPED_DOOR, OPENBIT)) {
        tell(" Close the door, huh?");
      }
      tell("\"");
    } else if (g.CLOWN_COUNTER == 6) {
      if (hasFlag(WARPED_DOOR, OPENBIT)) {
        g.FOLLOW_FLAG = 99;
        enable(await QUEUE(I_FOLLOW.id, 2));
        await PERFORM(V.RUB, JOEY);
        return true;
      } else {
        g.CLOWN_COUNTER = 7;
        tell("\n\"It'll be okay unless somebody tips him off about shoving Annie Oakley under the old front by the elephant tent --\"\n\nHis voice suddenly halts. ");
        await PERFORM(V.RUB, JOEY);
        return true;
      }
    } else {
      return false;
    }
    return crlf();
  }
}

async function UNMASK() {
  g.UNMASKED$ = true;
  disable(await INT(I_CLOWN_ALLEY.id));
  clearFlag(WARPED_DOOR, OPENBIT);
  setFlag(WARPED_DOOR, LOCKEDBIT);
  tell("ou're suddenly eye-to-eye with a very unhappy clown whose greasepaint red horseshoe smile practically melts off his face. \n\n");
  if (!(hasFlag(MASK, WORNBIT)) || (await HELD$(TRAY))) {
    tell("Snatching away the ");
    if (!(hasFlag(MASK, WORNBIT)) && (await HELD$(TRAY))) {
      await DPRINT(MASK);
      tell(" and the ");
      await DPRINT(TRAY);
      tell(", ");
    } else if (await HELD$(TRAY)) {
      await DPRINT(TRAY);
      tell(", ");
    } else {
      await DPRINT(MASK);
      tell(", ");
    }
  }
  move(TRAY, LOCAL_GLOBALS);
  tell("Chuckles seizes you by the scruff of your neck, and the irate clown hustles you out of the ");
  await DPRINT(CLOWN_TRAILER);
  tell(".\n\n");
  clearFlag(MASK, WORNBIT);
  move(MASK, LOCAL_GLOBALS);
  return await GOTO(WEST_CAMP);
}

async function TRAY_F() {
  if (isVerb(V.EMPTY, V.SEARCH) && (loc(ASH) == TRAY)) {
    await PERFORM(V.MOVE, ASH);
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await V_COUNT();
  } else {
    return false;
  }
}

async function ASH_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The ash, by its jet blackness, does not appear to be the remnant of tobacco.\n");
    return true;
  } else if (isVerb(V.TAKE, V.SEARCH, V.RUB, V.LOOK_INSIDE, V.LOOK_UNDER, V.MOVE)) {
    if (hasFlag(ASH, RMUNGBIT)) {
      tell("The ashes sift through your fingers.\n");
      return true;
    } else {
      setFlag(ASH, RMUNGBIT);
      move(SCRAP, TRAY);
      tell("In disturbing the ");
      await DPRINT(ASH);
      tell(", a ");
      await DPRINT(SCRAP);
      tell(" is revealed.\n");
      return true;
    }
  } else if (isVerb(V.EMPTY, V.DROP, V.POUR)) {
    move(ASH, LOCAL_GLOBALS);
    tell("The ashes swirl through the air and disappear");
    if ((hasFlag(ASH, RMUNGBIT) && (loc(SCRAP) == TRAY)) || !(hasFlag(ASH, RMUNGBIT))) {
      move(SCRAP, g.HERE);
      tell(" as a tiny ");
      await DPRINT(SCRAP);
      tell(" floats down");
    }
    tell(S(g.PERIOD));
    return true;
  } else {
    return false;
  }
}

async function SCRAP_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The ");
    await DPRINT(SCRAP);
    tell(" is about an inch square.\n");
    return true;
  } else if (isVerb(V.COMPARE) && (NOTE == g.PRSO || NOTE == g.PRSI)) {
    tell("The \"M\" on the ");
    await DPRINT(SCRAP);
    tell(" looks like it was cut from the the same newspaper as the letters on the ");
    await DPRINT(NOTE);
    tell(".\n");
    return true;
  } else if (isVerb(V.READ)) {
    tell("There's a paragraph of yak trivia on one side, and the letter \"M\" in 48-point type on the other.\n");
    return true;
  } else {
    return false;
  }
}

async function COSTUME_F() {
  if (isVerb(V.TAKE)) {
    tell("Nope, too repulsive.\n");
    return true;
  } else {
    return false;
  }
}

async function MIRROR_F() {
  if (isVerb(V.LOOK_INSIDE)) {
    if (hasFlag(MASK, WORNBIT)) {
      tell(S(g.YOU_SEE), " your beady eyes through the ");
      await DPRINT(MASK);
      tell(".\n");
      return true;
    } else {
      await PERFORM(V.EXAMINE, ME);
      return true;
    }
  } else {
    return false;
  }
}

async function BUNK_F() {
  if (isVerb(V.EXAMINE, V.LOOK_INSIDE) && (g.PRSO == UPPER) && (loc(THUMB) == g.HERE)) {
    await DPRINT(THUMB);
    tell(" is there. ");
    if (first(UPPER)) {
      return false;
    }
    crlf();
    return true;
  } else if (isVerb(V.BOARD, V.CLIMB_ON, V.CLIMB_FOO, V.THROUGH)) {
    if (g.PRSO == UPPER) {
      g.PRSO = CEILING;
      setFlag(UPPER, RMUNGBIT);
    } else {
      g.PRSO = UPPER;
      setFlag(LOWER, RMUNGBIT);
    }
    g.CLOCK_WAIT = true;
    await TELL_HIT_HEAD();
    if (hasFlag(UPPER, RMUNGBIT) && hasFlag(LOWER, RMUNGBIT)) {
      tell("Hadn't you really ought to stop trying to sleep around like this?\n");
      g.AWAITING_REPLY = 2;
      enable(await QUEUE(I_REPLY.id, 2));
      g.CLOCK_WAIT = true;
    }
    return true;
  } else {
    return false;
  }
}

async function WARPED_DOOR_F() {
  if (isVerb(V.OPEN, V.PICK) && !(hasFlag(WARPED_DOOR, OPENBIT)) && g.PRSI) {
    if (g.PRSI == CROWBAR) {
      g.WARPED_DOOR_BROKEN = true;
      setFlag(WARPED_DOOR, OPENBIT);
      clearFlag(WARPED_DOOR, LOCKEDBIT);
      clearFlag(CLOWN_ALLEY, TOUCHBIT);
      tell("You wedge the ");
      await DPRINT(CROWBAR);
      tell(" between the frame and the door then give it a yank. The ");
      await DPRINT(WARPED_DOOR);
      tell(" pops open.\n");
      return true;
    } else {
      tell(S(g.IT_LOOKS_LIKE));
      await ARTICLE(g.PRSI, true);
      tell(" is unequal to the task.\n");
      return true;
    }
  } else if (isVerb(V.OPEN, V.PICK) && !g.WARPED_DOOR_BROKEN && !g.PRSI && (await HELD$(CROWBAR))) {
    tell("(with the ");
    await DPRINT(CROWBAR);
    tell(")\n");
    await PERFORM(V.OPEN, WARPED_DOOR, CROWBAR);
    return true;
  } else if (isVerb(V.CLOSE) && g.WARPED_DOOR_BROKEN) {
    tell("The damaged door creaks back open.\n");
    return true;
  } else if (isVerb(V.CLOSE) && (g.HERE == WEST_CAMP) && (loc(JOEY) == CLOWN_ALLEY) && !(hasFlag(CLOWN_ALLEY, TOUCHBIT))) {
    setFlag(WARPED_DOOR, LOCKEDBIT);
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell(S(g.YOU_SEE), " that the door is warped slightly along its edge.\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    if (g.UNMASKED$ || hasFlag(WARPED_DOOR, RMUNGBIT) || (g.HERE == CLOWN_ALLEY) || !(g.CLOWN_COUNTER == 25)) {
      return false;
    } else {
      tell("Chuckles pops his head out from behind the ");
      await DPRINT(WARPED_DOOR);
      tell(" and ");
      if (hasFlag(MASK, WORNBIT) && !(hasFlag(SHAWL, WORNBIT)) && !(hasFlag(DRESS, WORNBIT))) {
        g.SCORE = g.SCORE + 10;
        g.CLOWN_COUNTER = 0;
        enable(await QUEUE(I_CLOWN_ALLEY.id, 3));
        setFlag(WARPED_DOOR, OPENBIT);
        clearFlag(WARPED_DOOR, LOCKEDBIT);
        tell("squints at you through a layer of cold cream, then flings the door open. He withdraws into the trailer.\n");
        return true;
      } else {
        setFlag(WARPED_DOOR, RMUNGBIT);
        enable(await QUEUE(I_CLOWN_ALLEY.id, 5));
        tell("shades his eyes to look at you. \"Beat it, lotlice,\" he says, withdrawing into the trailer and closing the door.\n");
        return true;
      }
    }
  } else {
    return false;
  }
}

